// Original LedgerSuite checks and CheckSuite grading; independent supplied rasters.
import org.audiveris.omr.sheet.Book;
import java.util.*;import java.lang.reflect.*;import java.nio.file.*;import java.awt.geom.*;
public class LedgerSuiteControlProbe extends LedgerCandidateControlProbe {
 public LedgerSuiteControlProbe(Book b,SortedSet<Integer> ids){super(b,ids);}
 public void process(){try{
  sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");call(make("sheet.grid.GridStep"),"doit",sheet);system=((List<?>)call(sheet,"getSystems")).get(0);Class<?> o=Class.forName("org.audiveris.omr.run.Orientation");vertical=o.getField("VERTICAL").get(null);horizontal=o.getField("HORIZONTAL").get(null);
  Object noStaff=Class.forName("org.audiveris.omr.sheet.Picture$SourceKey").getField("NO_STAFF").get(null);Object image=call(call(sheet,"getPicture"),"getSource",noStaff);byte[] pixels=(byte[])call(image,"getPixels");int w=(Integer)call(sheet,"getWidth"),h=(Integer)call(sheet,"getHeight");List<String> cases=new ArrayList<>();
  for(int il:new int[]{11,16,17,24})for(boolean wide:new boolean[]{false,true})for(int len:new int[]{il-1,il,il+1,(int)Math.rint(1.4*il),(int)Math.rint(1.5*il),2*il})for(int th:new int[]{1,2,7})for(int ends:new int[]{0,1,2})for(double offset:new double[]{0,.34*il,.35*il,Math.nextUp(.35*il)}){
   Arrays.fill(pixels,(byte)255);int x=100,y=50;List<String> black=new ArrayList<>();for(int n=0;n<ends;n++){int xx=n==0?x:x+len-1;call(image,"set",xx,y-1,0);black.add("["+xx+","+(y-1)+"]");}
   call(sheet,"setScale",make("sheet.Scale",make("sheet.Scale$InterlineScale",il,il,il),make("sheet.Scale$LineScale",2,2,2),null,null,null));Object builder=make("sheet.ledger.LedgersBuilder",system);call(get(builder,"minLengthLow"),"setValue",wide?1.4:1.);call(get(builder,"minLengthHigh"),"setValue",wide?2.:1.5);
   Object suite=make("sheet.ledger.LedgersBuilder$LedgerSuite",builder,call(call(sheet,"getScale"),"getInterlineScale"));Object f=make("glyph.dynamic.StraightFilament",il);call(f,"addSection",ledgerSection(1,y,x,len,th));double target=y+(th-1)/2.+offset;Object context=make("sheet.ledger.LedgersBuilder$StickContext",f,target);Object impacts=call(suite,"getImpacts",context);if(impacts==null)throw new AssertionError("suite failed");List<String> checks=new ArrayList<>();int i=0;List<?> weights=(List<?>)call(suite,"getWeights");for(Object check:(List<?>)call(suite,"getChecks")){Method value=check.getClass().getDeclaredMethod("getValue",context.getClass());value.setAccessible(true);checks.add("{\"name\":"+q(call(check,"getName"))+",\"raw_value\":"+value.invoke(check,context)+",\"low\":"+call(check,"getLow")+",\"high\":"+call(check,"getHigh")+",\"covariant\":"+call(check,"isCovariant")+",\"weight\":"+weights.get(i)+",\"impact\":"+call(impacts,"getImpact",i)+"}");i++;}
   Object old=vertical;vertical=horizontal;String ff;try{ff=filament(f);}finally{vertical=old;}
   double grade=(Double)call(impacts,"getGrade"),threshold=(Double)call(suite,"getMinThreshold");cases.add("{\"name\":"+q(il+"-"+wide+"-"+len+"-"+th+"-"+ends+"-"+offset)+",\"interline\":"+il+",\"fore\":2,\"wide_previous\":"+wide+",\"target_y\":"+target+",\"black_pixels\":["+String.join(",",black)+"],\"filament\":"+ff+",\"result\":{\"checks\":["+String.join(",",checks)+"],\"grade\":"+grade+",\"min_threshold\":"+threshold+",\"accepted\":"+(grade>=threshold)+"}}");
  }
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"width\":"+w+",\"height\":"+h+",\"scope\":\"Unmodified original LedgerSuite/Check/CheckSuite; real GRID sheet, independent supplied rectangle filaments, declared target ordinate and white NO_STAFF raster plus listed black endpoint neighbors. No staff reference selection or ledger registration claim.\",\"cases\":["+String.join(",",cases)+"]}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
